/**
 * The prayer city catalogue (wiki Epic 21 §3, E21-D3): GeoNames cities of 15,000 people or more
 * (CC BY 4.0), generated by scripts/build-prayer-cities.ts into cities.data.ts. Apps bundle the
 * same ids, so a city id is the only location value that ever reaches the server.
 *
 * The 1.8 MB table is loaded with a dynamic import on the first city lookup, so the Worker's
 * entry does not evaluate it on every cold start: only isolates that serve a prayer request
 * pay for it, once. A lookup scans the packed text for one id instead of parsing every city.
 */
let table: Promise<string> | null = null;
function citiesTable(): Promise<string> {
	table ??= import('./cities.data').then((m) => m.PRAYER_CITIES_TSV);
	return table;
}

export interface PrayerCity {
	id: string;
	latitude: number;
	longitude: number;
	country: string;
	timeZone: string;
	name: string;
}

export const CITY_ID = /^[1-9][0-9]{0,9}$/;

function parse(line: string): PrayerCity | null {
	const [id, lat, lon, country, timeZone, name] = line.split('\t');
	if (!id || !timeZone) return null;
	return { id, latitude: Number(lat), longitude: Number(lon), country, timeZone, name };
}

export async function findCity(id: string): Promise<PrayerCity | null> {
	if (!CITY_ID.test(id)) return null;
	return findCityIn(await citiesTable(), id);
}

/** The lookup itself, on a given table (tests pass a small one). */
export function findCityIn(data: string, id: string): PrayerCity | null {
	if (!CITY_ID.test(id)) return null;
	const at = data.indexOf(`\n${id}\t`);
	if (at < 0) return null;
	const end = data.indexOf('\n', at + 1);
	return parse(data.slice(at + 1, end < 0 ? undefined : end));
}
